<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$mensaje='';$error='';$uid=(int)($_SESSION['farmacia_usuario_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$accion=$_POST['accion']??'';$pass=$_POST['contrasena']??'';if(strlen($pass)<12)$error='Usa una contraseña de al menos 12 caracteres.';elseif($accion==='cambiar'){$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$mysqli->prepare('UPDATE usuarios SET password_hash=? WHERE id=?');$s->bind_param('si',$hash,$uid);$mensaje=$s->execute()?'Contraseña actualizada.':'No se pudo actualizar.';$s->close();}elseif($accion==='crear'){$nombre=trim($_POST['nombre']??'');$correo=trim($_POST['correo']??'');$hash=password_hash($pass,PASSWORD_DEFAULT);if($nombre===''||!filter_var($correo,FILTER_VALIDATE_EMAIL))$error='Nombre o correo inválido.';else{$s=$mysqli->prepare('INSERT INTO usuarios(nombre,correo,password_hash) VALUES(?,?,?)');$s->bind_param('sss',$nombre,$correo,$hash);$mensaje=$s->execute()?'Usuario agregado.':'No se pudo agregar; revisa si el correo ya existe.';$s->close();}}}
$usuarios=$mysqli->query('SELECT nombre,correo,activo FROM usuarios ORDER BY nombre');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios</title><style>body{font:15px Arial;background:#f2f7f5;color:#243b37;margin:0}.wrap{padding:22px}.box{background:white;padding:22px;border-radius:12px;margin-bottom:15px}h1,h2{color:#087f73}label{display:block;margin:9px 0 5px}input,button{padding:10px;border:1px solid #ccd;border-radius:7px}button,.btn{background:#087f73;color:#fff;border:0;padding:10px 14px;border-radius:7px;text-decoration:none}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #ddd}</style></head><body><main class="wrap"><h1>Usuarios y contraseña</h1><?php if($mensaje||$error)echo '<p>'.htmlspecialchars($mensaje?:$error).'</p>';?><div class="box"><h2>Cambiar mi contraseña</h2><form method="post"><input type="hidden" name="accion" value="cambiar"><label>Nueva contraseña (mínimo 12 caracteres)</label><input type="password" name="contrasena" minlength="12" required><button>Actualizar contraseña</button></form></div><div class="box"><h2>Crear usuario</h2><form method="post"><input type="hidden" name="accion" value="crear"><label>Nombre</label><input name="nombre" required><label>Correo</label><input type="email" name="correo" required><label>Contraseña (mínimo 12 caracteres)</label><input type="password" name="contrasena" minlength="12" required><button>Crear usuario</button></form></div><div class="box"><h2>Usuarios registrados</h2><table><thead><tr><th>Nombre</th><th>Correo</th><th>Estado</th></tr></thead><tbody><?php while($u=$usuarios->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($u['nombre'])?></td><td><?=htmlspecialchars($u['correo'])?></td><td><?=$u['activo']?'Activo':'Inactivo'?></td></tr><?php } ?></tbody></table><p><a class="btn" href="index.php">Volver</a></p></div></main></body></html>
